pub fn deref(self: *SharedGridSet, key: Key) void {
    self.lock.lockUncancelable(global.io());
    defer self.lock.unlock(global.io());

    const entry = self.map.getEntry(key) orelse return;
    assert(entry.value_ptr.ref >= 1);

